package macro;
import star.common.*;import star.metrics.*;import star.base.neo.*;import star.base.report.*;import star.meshing.*;import star.material.*;import star.flow.*;import star.segregatedflow.*;import star.turbulence.*;import star.kwturb.*;import star.motion.*;import star.vis.*;import star.sweptmesher.*;import star.prismmesher.*;import java.nio.file.*;import java.io.*;import java.util.*;
public class PrepareStaticFlap extends StarMacro {

Simulation s;Path root=Paths.get("F:/ntnu/flap_control/hydro_validation_2606_20261102"),out;List<Region> regions=new ArrayList<>();List<Boundary> fixed=new ArrayList<>(),flap=new ArrayList<>();double xh=.952,zh=.02128173276776986;String variant;
void note(String text)throws Exception{s.println("HYDRO_STAGE "+text);Files.writeString(out.resolve("progress.txt"),text+"\n");}
void guard()throws Exception{if(Files.exists(root.getParent().resolve("PAUSED_FOR_HOME.json")))throw new IllegalStateException("Paused");if(s.getNumberOfGpgpus()!=0)throw new IllegalStateException("CPU-only working model");s.getSimulationIterator().getAutoSave().setEnabled(false);s.getSimulationIterator().getAutoSave().setAutoSaveBatch(false);}
UserFieldFunction field(String name,String definition,Dimensions dimensions){UserFieldFunction f=s.getFieldFunctionManager().createFieldFunction();f.setPresentationName(name);f.setFunctionName(name);f.getTypeOption().setSelected(FieldFunctionTypeOption.Type.SCALAR);f.setDimensions(dimensions);f.setDefinition(definition);return f;}
void constant(ScalarProfile p,double v){p.setMethod(ConstantScalarProfileMethod.class);p.getMethod(ConstantScalarProfileMethod.class).getQuantity().setValue(v);}
void velocity(VectorProfile p){p.setMethod(ConstantVectorProfileMethod.class);p.getMethod(ConstantVectorProfileMethod.class).getQuantity().setComponents(18,0,0);}
void pressure(ScalarProfile p,FieldFunction f){p.setMethod(FunctionScalarProfileMethod.class);p.getMethod(FunctionScalarProfileMethod.class).setFieldFunction(f);}
void turbulence(Boundary b){b.getConditions().get(KwTurbSpecOption.class).setSelected(KwTurbSpecOption.Type.INTENSITY_VISCOSITY_RATIO);constant(b.getValues().get(TurbulenceIntensityProfile.class),.001);constant(b.getValues().get(TurbulentViscosityRatioProfile.class),10);}
void scene()throws Exception{
Scene sc=s.getSceneManager().createScene("HYDRO foil and mesh");sc.initializeAndWait();int k=0;for(Region r:regions){PlaneSection p=s.getPartManager().createImplicitPart(List.of(r),List.of(0.,1.,0.),List.of(0.,.02,0.),0,1,new DoubleVector(new double[]{0}));p.setPresentationName("HYDRO midspan "+r.getPresentationName());PartDisplayer d=sc.getDisplayerManager().createPartDisplayer(r.getPresentationName(),-1,1);d.getInputParts().setObjects(p);d.setMesh(true);d.setSurface(false);d.setOutline(false);d.setDisplayerColor(new DoubleVector(k++==0?new double[]{.25,.35,.45}:new double[]{.95,.3,.1}));}
PartDisplayer w=sc.getDisplayerManager().createPartDisplayer("Foil", -1,1);List<Boundary> all=new ArrayList<>(fixed);all.addAll(flap);w.getInputParts().setObjects(all);w.setSurface(true);w.setOutline(true);w.setDisplayerColor(new DoubleVector(new double[]{.1,.4,.75}));
sc.getCurrentView().setInput(new DoubleVector(new double[]{.60,.02,.025}),new DoubleVector(new double[]{.60,-3,.025}),new DoubleVector(new double[]{0,0,1}),.68,1,s.getCoordinateSystemManager().getLabCoordinateSystem(),false);sc.printAndWait(out.resolve("mesh_foil.png").toString(),1,1300,700);
sc.getCurrentView().setInput(new DoubleVector(new double[]{xh,.02,zh}),new DoubleVector(new double[]{xh,-3,zh}),new DoubleVector(new double[]{0,0,1}),.065,1,s.getCoordinateSystemManager().getLabCoordinateSystem(),false);sc.printAndWait(out.resolve("mesh_hinge.png").toString(),1,1100,800);
}

FieldFunction namedField(String display,String fallback){if(s.getFieldFunctionManager().hasFunction(fallback))return s.getFieldFunctionManager().getFunction(fallback);for(FieldFunction f:s.getFieldFunctionManager().getObjects())if(f.getPresentationName().equals(display))return f;throw new IllegalStateException("Required field absent: "+display);}
ElementCountReport count(String name,FieldFunction ff,double lo,double hi,Representation rep){ThresholdPart p=s.getPartManager().createThresholdPart();p.setPresentationName(name);p.getInputParts().setObjects(regions);p.setFieldFunction(ff);p.setRange(new DoubleVector(new double[]{lo,hi}));p.setMode(ThresholdMode.BETWEEN_TAG);ElementCountReport r=s.getReportManager().createReport(ElementCountReport.class);r.setPresentationName(name);r.getParts().setObjects(p);r.setRepresentation(rep);return r;}
public void execute(){s=getActiveSimulation();variant="SP_C";Path input=Paths.get(System.getProperty("NTNU_HYDRO_INPUT_OVERRIDE",s.getSessionPath())).toAbsolutePath().normalize(),base=input.getParent();String id=System.getenv("NTNU_HYDRO_RUN_ID");double angle=Double.parseDouble(System.getenv("NTNU_HYDRO_ANGLE_DEG"));List<Solver> frozen=new ArrayList<>();out=root.resolve("cases/SP_C_split0_overset/static_"+(angle<0?"minus":"plus")+Math.round(Math.abs(angle))+"_"+id);
try{if(!input.startsWith(root.resolve("cases/SP_C_split0_overset"))||!List.of(2.,-2.,5.,-5.).contains(angle))throw new IllegalStateException("Approved static pose and owned SP_C required");Files.createDirectories(out);guard();String parentStatus=Files.readString(base.resolve("status.json"));if(!parentStatus.contains("force_stabilization_passed"))throw new IllegalStateException("Parent static stabilization must pass before next angle");
Region bg=s.getRegionManager().getRegion("Background"),ov=s.getRegionManager().getRegion("FlapOverset");regions.add(bg);regions.add(ov);for(Region r:regions)for(Boundary b:r.getBoundaryManager().getBoundaries())if(b.getBoundaryType() instanceof WallBoundary&&!b.getPresentationName().endsWith("bottom")){if(r==ov)flap.add(b);else fixed.add(b);}
RotatingMotion rotation=(RotatingMotion)ov.getValues().get(MotionSpecification.class).getMotion();if(!s.getSolution().isInitialized())s.getSolution().initializeSolution();double t0=s.getSolution().getPhysicalTime();
for(Solver solver:s.getSolverManager().getObjects())if(solver instanceof SegregatedFlowSolver||solver.getClass().getName().toLowerCase(Locale.ROOT).contains("turb"))if(!solver.getFrozen()){solver.setFrozen(true);frozen.add(solver);}
((RotationAngle)rotation.getRotationSpecification()).getRotationAngle().setDefinition("<"+angle+" deg>");s.getSolverManager().getSolver(ImplicitUnsteadySolver.class).getTimeStep().setValue(.0004);for(SolverStoppingCriterion c:s.getSolverStoppingCriterionManager().getObjects()){c.setIsUsed(false);if(c instanceof InnerIterationStoppingCriterion){c.setIsUsed(true);((InnerIterationStoppingCriterion)c).setMaximumNumberInnerIterations(1);}}
s.getSimulationIterator().step(1);
Vector3 measured=rotation.transformInitialCoordinate(new Vector3(xh+.2,.02,zh));double actual=-Math.toDegrees(Math.atan2(measured.z-zh,measured.x-xh));Representation rep=(Representation)s.getRepresentationManager().getObject("Overset Mesh");ElementCountReport errors=count("Static pose connectivity errors",namedField("Overset Error Status","OversetErrorStatus"),.5,100,rep);double err=errors.getReportMonitorValue();if(Math.abs(actual-angle)>.01||err!=0||!(s.getReportManager().getReport("HF_min_volume").getReportMonitorValue()>0&&s.getReportManager().getReport("HF_min_quality").getReportMonitorValue()>0))throw new IllegalStateException("Static pose geometry/connectivity check failed");
for(Solver solver:frozen)solver.setFrozen(false);for(SolverStoppingCriterion c:s.getSolverStoppingCriterionManager().getObjects())if(c instanceof InnerIterationStoppingCriterion)((InnerIterationStoppingCriterion)c).setMaximumNumberInnerIterations(15);
Files.copy(base.resolve("normalization.json"),out.resolve("normalization.json"));Files.writeString(out.resolve("pose.json"),"{\"target_angle_deg\":"+angle+",\"measured_angle_deg\":"+actual+",\"overset_error_cells\":"+err+",\"source_time_s\":"+t0+",\"pose_step_flow_frozen\":true,\"training_approved\":false}");scene();s.saveState(out.resolve("pose_ready.sim").toString());note("Pose verified; warm fields require new numerical initialization and stabilization");
}catch(Exception e){for(Solver solver:frozen)solver.setFrozen(false);try{Files.writeString(out.resolve("pose_error.txt"),e.toString());s.saveState(out.resolve("pose_error.sim").toString());}catch(Exception ignored){}throw new RuntimeException(e);}}
}
